// Teacher frames: FULL figures (no head/body split).
// Base64 data URIs so no binary PNG has to be pushed to GitHub.
// Frame 0 is the base TEACHER_IMG (mouth closed, eyes open).
// The variants are the user-made images, checkerboard removed,
// face-centroid aligned to the base so swapping frames never
// moves the body. Blink = eyes gently closed, happy = big smile.
export const FRAME_SLIGHT = "data:image/png;base64,";
export const FRAME_WIDE = "data:image/png;base64,";
export const FRAME_BLINK = "data:image/png;base64,";
export const FRAME_HAPPY = "data:image/png;base64,";
